import React from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';
// import './YourCustomStyles.css'; // Assuming you have additional custom styles
import TypingAnimation from './typingAnimation';
import { Link } from 'react-router-dom';
import "../App.css";
import yasirImage from '../assets/yasir.png'; // Adjust the path based on where you place the image


const Home = () => {
  return (
    <>
      
      <div className='p-5 d-flex justify-content-center align-items-center vh-100'>
        <div className="card-7 rounded p-md-5 text-white border d-flex row mains"
        style={{    boxShadow: "rgba(6, 24, 44, 0.4) 0px 0px 0px 2px, rgba(6, 24, 44, 0.65) 0px 4px 6px -1px, rgba(255, 255, 255, 0.08) 0px 1px 0px inset"
        }}
        >
          <div
            className="rounded shadow-lg h-100 col-12 col-md-3 col-lg-3 d-md-block d-none"
            style={{
              marginLeft: '-65px',
              top: '60%',
              width: '15rem',
              background: 'linear-gradient(45deg, #f8523b, red)',
            }}
          >
            <img
              src={yasirImage}
              className="img-fluid rounded-3 bg-custom about-imgg "
              alt="Profile"
            />
          </div>

          <div
            className="rounded shadow-lg col-12 col-md-3 col-lg-3 d-md-none justify-content-center flex-column d-flex align-items-center"
            style={{
              height:"20rem",
              
              background: 'linear-gradient(45deg, #f8523b, red)',
            }}
          >
            <div className='h-100'> 
            <img
              src={yasirImage}
              className="img-fluid rounded-3 bg-custom about-imgg h-100 "
              alt="Profile"
            />
            </div>
          </div>

          <div className="col-12 col-md-9 col-lg-9 ps-5 pe-0 cont  text-dark justify-content-center flex-column d-flex">
          <h1
            className="p-0 m-0 py-2   d-md-none"
            style={{
              fontWeight: 800,
              color: '#000000',
              fontSize: "30px",
              letterSpacing: '9px',
            }}
          >
           Yasir <span className="heading-typing"> <TypingAnimation /> </span>
          </h1>
          <span
            className="p-0 m-0 py-2   d-none d-md-block"
            style={{
              fontWeight: 800,
              color: '#000000',
              letterSpacing: '9px',
              fontSize: "50px"
            }}
          >
            Yasir <span className="heading-typing"> <TypingAnimation /> </span>
          </span>
          <div className="verticalflip w-100 justify-content-start d-flex align-items-start text-dark">
            &nbsp;
            <span className="text-dark">MERN Stack Developer</span>
            <span className="text-dark">Full Stack Developer</span>
            <span className="text-dark">Wordpress Developer</span>
          </div>
            <p className='p-0 m-0 mb-3 d-md-none'>
            Crafting seamless digital experiences from front to back – Explore the world of Full Stack Development with me!
            </p>
            <p className='p-0 m-0 mb-3 d-none d-md-block d-lg-block'>
            Full Stack Web Developer with a passion for crafting intuitive interfaces and powerful back-end systems. From front-end design to back-end logic, I build web experiences that are both beautiful and functional. Let's turn ideas into impactful digital solutions!
            </p>
            <div>
              <Link to="/portfolio">
                <button className="w-50 btn btn-lg bg-custom text-white my-work" 
                 style={{
                  background: 'linear-gradient(45deg, #f8523b, red)',
                }}
                >
                  My Work
                </button>
              </Link>
            </div>
          </div>
        </div>
      </div>
    </>
  );
};

export default Home;
