import { Routes, Route, Navigate, useNavigate } from "react-router-dom";
import { useState, useEffect } from "react";
import AboutUsPage from "./pages/AboutUs";
import Home from "./pages/HomeDesign";
import SkillsAndExperience from "./pages/SkillsSection";
import Navbar from "./pages/Navbar";
import Portfolio from "./pages/Portfolio";
import ContactSection from "./pages/ContactUs";
import Progressbar from "./pages/Progressbar/Progressbar";
import Skills from "./pages/Skills";
const AppRouter = () => {
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate(); // Get the navigate function

  useEffect(() => {
    const timer = setTimeout(() => {
      setLoading(false);
    }, 3000);

    return () => clearTimeout(timer);
  }, []);

  // Define the navigateTo function
  const navigateTo = (path) => {
    navigate(path); // Use the navigate function from React Router
  };

  return (
    <>
      {loading ? (
        <Progressbar />
      ) : (
        <>
          <Navbar navigateTo={navigateTo} /> {/* Pass navigateTo as a prop */}
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/home" element={<Home />} />
            <Route path="/aboutus" element={<AboutUsPage />} />
            <Route path="/experience" element={<SkillsAndExperience />} />
            <Route path="/skillss" element={<Skills />} />
            
            <Route path="/portfolio" element={<Portfolio />} />
            <Route path="/contact" element={<ContactSection />} />
            <Route path="*" element={<Navigate to="/" />} />
          </Routes>
        </>
      )}
    </>
  );
};

export default AppRouter;
